#!/bin/sh
# Purpose: selftest case — the hold, the queue and the owner's answers (v0.26.10.24.6 R3, R4). A second run adds no count; a wait adds none; failing at two heads
# holds; missing in two reports holds; a failing row with evidence missing counts once; acceptance starts a row not held again; a held row stays held at a new
# head that passes, and in another ticket; more twice, its row going failing. accept refused on a failing row and on a row not held; each answer recorded;
# a ruled row's line, its evidence still missing, adding no count, and the ticket accepted with it; a failed test at a later head undoing accept. The queue.
# v0.26.10.25.5: a row landed after the ticket was published, no evidence from it and nothing from a decision before it. Env: CHECKS.
# selftest-limit: 2880 s — 636 to 952 s alone under load, 911 s and more in the suite (the runner's rule, ×3)
set -eu
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
. "$CHECKS/selftest/fixtures/tickets.sh"
. "$CHECKS/selftest/fixtures/results-reports.sh"
fail() { echo "decide-hold: $*" >&2; cat "$T/out" >&2 2>/dev/null; exit 1; }
RS=$CHECKS/results.sh; DS=$CHECKS/decide.sh; rr_project; : > .vid/RUN-STATE.md; printf 'repo: owner/code\nlabels-prefix:\n' > .vid/tw/settings
git init -q --bare "$T/code.git"; gh_fake; mv "$T/bin/gh" "$T/bin/gh-fake"
cat > "$T/bin/gh" <<'G'
#!/bin/sh
case "$1 $2 ${7:-}" in 'pr view labels') echo; exit 0 ;; esac
exec "$(dirname "$0")/gh-fake" "$@"
G
chmod +x "$T/bin/gh"; for n in 3 5; do mkdir -p "$T/gh/issues/$n/comments"; echo OPEN > "$T/gh/issues/$n/state"; done; mkdir -p "$T/gh/prs/4/comments"
for n in 3 4 5 6 7; do echo "$n" > "$T/w/n$n"; git -C "$T/w" add -A; rr_git -C "$T/w" commit -qm "n$n"; eval "C$n=\$(git -C \"\$T/w\" rev-parse HEAD)"; done; git -C "$T/w" push -q "$T/p/.vid/code" main
# fresh: these rounds read each head on its own; KEEP=1 keeps the earlier set
fresh() { [ -n "${KEEP:-}" ] && return 0; for f in .vid/decide/pr-*.rows; do [ -f "$f" ] && awk -F'\t' -v OFS='\t' '{ $10 = 0; print }' "$f" > "$T/rw" && cat "$T/rw" > "$f"; done; return 0; }
dc() { fresh; sh "$RS" read --ticket 3 --pr 4 --head "$1" > /dev/null 2>&1; sh "$DS" decide --ticket 3 --pr 4 --head "$1" > "$T/out" 2>&1 || fail 'decide failed'; }
is() { grep -q "^$1 $2" "$T/out" || fail "no line: $1 $2"; }
n() { awk -v r="$1" '$1 == r { c++ } END { print c + 0 }' .vid/decide/counts; }
# head <commit> <row=result…>: a report, every row passing but those named, with the faults proven; WK names a row whose own fault is not proven
head_() { c=$1; shift; h=$(printf %s "$c" | cut -c1-12); A=pr-4-$h-1; rr_put "$A" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2\n%s' "$c" "${RL:-}")"; rr_put "$A" cases-alpha.xml "$(rr_cases "$@")"; if [ -n "${WK:-}" ]; then rr_put "$A" faults/$WK/control.txt ROW-009; rr_put "$A" faults/$WK/cases-alpha.xml "$(rr_cases "$WK=pass" ROW-009=pass)"; fi
  rr_put "$A" faults/ROW-002-T1/control.txt ROW-009; rr_put "$A" faults/ROW-002-T1/cases-alpha.xml "$(rr_cases ROW-002-T1=fail:x ROW-009=pass)"; rr_put "$A" faults/HOS-001/control.txt ROW-009; rr_put "$A" faults/HOS-001/cases-alpha.xml "$(rr_cases 'HOS-001=fail:x&#10;vid-forbidden-effect: HOS-001' ROW-009=pass)"; rr_send "$A"; }
rr_good
# a failing row: once a head, however often decided; a wait adds none; acceptance starts it again
OK='ROW-002-T1=pass ROW-002-T2=pass HOS-001=pass RULE-001=pass ROW-009=pass'
head_ "$RR_H" ROW-001=fail:no $OK; dc "$RR_H"; dc "$RR_H"; [ "$(n ROW-001)" = 1 ] || fail 'a second run added a count'; is ROW-001 'failing, a product failure'
echo blocked > "$T/gh/issues/3/labels"; head_ "$RR_H2" ROW-001=pass $OK; dc "$RR_H2"; is ROW-001 'question open'; [ "$(n ROW-001)" = 1 ] || fail 'a wait added a count'; : > "$T/gh/issues/3/labels"
head_ "$C3" ROW-001=pass $OK; dc "$C3"; is ROW-001 'accepted$'; [ "$(n ROW-001)" = 0 ] || fail 'acceptance did not start the row again'
# failing at two heads holds; it stays held at a head that passes, and in another ticket; a failing row with evidence missing counts once
WK=ROW-001; head_ "$C4" ROW-001=pass $OK; WK=''; dc "$C4"; is ROW-001 'failing'; WK=ROW-001; head_ "$C5" ROW-001=pass $OK; WK=''; dc "$C5"; is ROW-001 'held — failing, a weak test'; grep -qx 'row ROW-001 held | stand-in: decision' .vid/tw/handed || fail 'no held line'; [ "$(n ROW-001)" = 2 ] || fail 'a row with evidence missing counted twice'
head_ "$C6" ROW-001=pass $OK; dc "$C6"; is ROW-001 'held — it passes'; is 'ticket:' 'not yet'
sed 's/- rows: x/- rows: x/' .vid/tw/out/issue-3.md > .vid/tw/out/issue-5.md; sh "$RS" read --ticket 5 --pr 4 --head "$C6" > /dev/null; sh "$DS" decide --ticket 5 --pr 4 --head "$C6" > "$T/out" 2>&1; is ROW-001 'held'; dc "$C6"
# the queue
sh "$DS" queue > "$T/q" 2>&1 || fail 'no queue'; grep -q 'ROW-001' .vid/decide/queue.md && grep -q 'accept it by ruling' .vid/decide/queue.md && grep -q 'a stray route\|Findings' .vid/decide/queue.md && [ -f .vid/decide/queue.html ] || fail 'the queue page'
# accept refused on a row held for a failure, and on a row not held; more twice; limit; amend recorded
RC=0; sh "$DS" rule ROW-001 accept > "$T/out" 2>&1 || RC=$?; [ "$RC" = 1 ] || fail 'accept on a row that passes with no evidence missing'; RC=0; sh "$DS" rule ROW-009 accept > "$T/out" 2>&1 || RC=$?; [ "$RC" = 1 ] && grep -q 'is not held' "$T/out" || fail 'accept on a row not held'
sh "$DS" rule ROW-001 more 1 --by the-owner > "$T/out"; grep -qx 'row ROW-001 failing | stand-in: decision' .vid/tw/handed || fail 'more wrote no failing line'; grep -q 'more	1	the-owner' .vid/decide/rulings || fail 'more not recorded'; dc "$C6"; is ROW-001 'accepted$'; [ "$(n ROW-001)" = 0 ] || fail 'acceptance after more'; grep -q '^row ROW-001 ' .vid/tw/handed && fail 'an unmerged row left on the handed record'
WK=ROW-001; head_ "$C7" ROW-001=pass $OK; WK=''; dc "$C7"; is ROW-001 failing; [ "$(n ROW-001)" = 1 ] || fail 'the count after more'
WK=ROW-001; rr_git -C "$T/w" commit -q --allow-empty -m m1; M1=$(git -C "$T/w" rev-parse HEAD); git -C "$T/w" push -q "$T/p/.vid/code" main; head_ "$M1" ROW-001=pass $OK; WK=''; dc "$M1"; is ROW-001 'held'; sh "$DS" rule ROW-001 more 2 > "$T/out"; [ "$(awk '$1 == "ROW-001" { print $2 }' .vid/decide/limits)" = 4 ] || fail 'a second more: its count now plus n'; sh "$DS" rule ROW-001 more 1 > "$T/out" 2>&1 && fail 'more on a row not held'
# missing in two reports holds; accept on it, a ruled row adding no count, the ticket accepted with it; a later failed test undoes it; limit; answer
A=pr-4-$(printf %s "$C7" | cut -c1-12); rm -rf "$T/r/$A-1/faults/HOS-001" "$T/r/$A-1/faults/ROW-001"; echo 'retested: HOS-001' >> "$T/r/$A-1/results.txt"; rr_send "$A-1"; dc "$C7"; is HOS-001 'evidence missing'; [ "$(n HOS-001)" = 1 ] || fail 'one report, one count'
mkdir -p "$T/r/$A-2"; cp -R "$T/r/$A-1/." "$T/r/$A-2/"; rr_send "$A-2"; dc "$C7"; is HOS-001 'held — evidence missing'
sh "$DS" rule HOS-001 accept --by the-owner > "$T/out" || fail 'accept refused'; dc "$C7"; is HOS-001 'accepted by ruling'; [ "$(n HOS-001)" = 0 ] || fail 'a ruled row counted'; grep -q '^row HOS-001 ' .vid/tw/handed && fail "a ruling's word on an unmerged ticket"
dc "$C7"; is 'ticket:' accepted; sh "$DS" merged --pr 4 > /dev/null; grep -q 'row HOS-001 accepted-by-ruling' .vid/tw/handed || fail 'no ruling on the record at the merge'
rr_git -C "$T/w" commit -q --allow-empty -m n8; C8=$(git -C "$T/w" rev-parse HEAD); git -C "$T/w" push -q "$T/p/.vid/code" main; head_ "$C8" ROW-001=pass ROW-002-T1=pass ROW-002-T2=pass HOS-001=fail:broke RULE-001=pass ROW-009=pass; dc "$C8"; is HOS-001 'failing'; grep -q 'row HOS-001 failing' .vid/tw/handed || fail 'a later failure did not undo accept'
sh "$RS" read --ticket 3 --pr 4 --head "$C8" > /dev/null; rr_git -C "$T/w" commit -q --allow-empty -m n9; C9=$(git -C "$T/w" rev-parse HEAD); git -C "$T/w" push -q "$T/p/.vid/code" main; head_ "$C9" ROW-001=pass ROW-002-T1=pass ROW-002-T2=pass HOS-001=fail:broke RULE-001=pass ROW-009=pass; dc "$C9"; is HOS-001 held
sh "$DS" rule HOS-001 limit > "$T/out"; dc "$C9"; is HOS-001 'known limit'; sh "$DS" rule SEAM-001 limit > "$T/out" 2>&1 || fail 'limit refused on a row a decision has read'; sh "$DS" rule ROW-777 limit > "$T/out" 2>&1 && fail 'limit on an id no decision holds'; sh "$DS" rule SEAM-001 accept > "$T/out" 2>&1 && fail 'accept on a row not held'
# accept wants a test that passed: a head report refused twice holds a row with no T3, and accept is refused
rr_git -C "$T/w" commit -q --allow-empty -m m2; M2=$(git -C "$T/w" rev-parse HEAD); git -C "$T/w" push -q "$T/p/.vid/code" main; m=$(printf %s "$M2" | cut -c1-12); rr_put "pr-4-$m-1" results.txt "$(printf 'by: TM\ncommit: %s' "$M2")"; rr_send "pr-4-$m-1"; dc "$M2"; rr_put "pr-4-$m-2" results.txt "$(printf 'by: TM\ncommit: %s' "$M2")"; rr_send "pr-4-$m-2"; dc "$M2"; is ROW-009 'held — evidence missing'
RC=0; sh "$DS" rule ROW-009 accept > "$T/out" 2>&1 || RC=$?; [ "$RC" = 1 ] || fail 'accept with no test seen to pass'
rr_git -C "$T/w" commit -q --allow-empty -m m6; M6=$(git -C "$T/w" rev-parse HEAD); git -C "$T/w" push -q "$T/p/.vid/code" main; head_ "$M6" ROW-001=pass $OK
# a journey's hold: more on each held transition frees a count on the journey; more on a row held by a transition frees it; a transition ruled a limit holds no row of its journey
printf 'ROW-002 a\nROW-002 b\n' >> .vid/decide/counts; dc "$M6"; is ROW-002-T1 held; sh "$DS" rule ROW-002-T1 more 1 > /dev/null; sh "$DS" rule ROW-002-T2 more 1 > /dev/null; dc "$M6"; is ROW-002-T1 accepted; is ROW-002-T2 accepted
printf 'ROW-009-T1 a\nROW-009-T1 b\n' >> .vid/decide/counts; dc "$M6"; is ROW-009 held; sh "$DS" rule ROW-009 more 1 > /dev/null; dc "$M6"; is ROW-009 passing; printf 'ROW-009-T2 a\nROW-009-T2 b\n' >> .vid/decide/counts; dc "$M6"; is ROW-009 held; printf 't\tROW-009-T2\tlimit\t\tx\t\n' >> .vid/decide/rulings; dc "$M6"; is ROW-009 passing
# J13, on a pull request of its own, each scene from an empty record: a first failure is not held, and comes back held if it fails again; a row that passes and comes back is held, and more clears that; a held row leaves another its round; a weak test's row goes to the fixer unheld, and passes clean; inconclusive; a transition ruled a limit
KEEP=1; mkdir -p "$T/gh/prs/6/comments" "$T/gh/prs/8/comments"; nh() { rr_git -C "$T/w" commit -q --allow-empty -m "$1"; X=$(git -C "$T/w" rev-parse HEAD); git -C "$T/w" push -q "$T/p/.vid/code" main; h=$(printf %s "$X" | cut -c1-12); }; d6() { sh "$RS" read --ticket 3 --pr 6 --head "$X" > /dev/null 2>&1; sh "$DS" decide --ticket 3 --pr 6 --head "$X" > /dev/null 2>&1; sh "$DS" decide --ticket 3 --pr 6 --head "$X" > "$T/out" 2>&1 || fail 'decide failed'; }
r6() { rr_put "pr-6-$h-1" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$X")"; rr_put "pr-6-$h-1" cases-alpha.xml "$(rr_cases "$@")"; rr_put "pr-6-$h-1" faults/ROW-002-T1/control.txt ROW-009; rr_put "pr-6-$h-1" faults/ROW-002-T1/cases-alpha.xml "$(rr_cases ROW-002-T1=fail:x ROW-009=pass)"; rr_put "pr-6-$h-1" faults/HOS-001/inconclusive.txt 'it would not plant'; rr_send "pr-6-$h-1"; d6; }
J='ROW-002-T1=pass ROW-009=pass RULE-001=pass HOS-001=pass'; rm -rf .vid/decide; nh z1; r6 ROW-001=fail:a ROW-002-T2=pass $J; is ROW-001 'failing, a product'; is HOS-001 'accepted$'; nh z2; r6 ROW-001=pass ROW-002-T2=fail:b $J; is ROW-002-T2 'held — it did not shrink — failing, a product'; is ROW-001 'accepted$'; nh z3; r6 ROW-001=pass ROW-002-T2=fail:b $J; is ROW-002-T2 'held — it did not shrink'
rm -rf .vid/decide; nh a1; r6 ROW-001=fail:a ROW-002-T2=pass $J; nh a2; r6 ROW-001=fail:a ROW-002-T2=pass $J; nh a3; r6 ROW-001=fail:a ROW-002-T2=pass $J; is ROW-001 'held — it did not shrink — failing, a product'; grep -qx '6	ROW-001' .vid/decide/halted || fail 'no halt on record'; nh a4; J2='ROW-002-T1=pass ROW-009=pass RULE-001=pass HOS-001=fail:c'; r6 ROW-001=fail:a ROW-002-T2=pass $J2; is ROW-001 held; is HOS-001 'held — it did not shrink'; sh "$DS" rule ROW-001 more 3 > "$T/q"; sh "$DS" rule HOS-001 more 3 > "$T/q"; d6; [ -s .vid/decide/halted ] && fail 'more left the halt'; nh a5; r6 ROW-001=fail:a ROW-002-T2=pass $J2; [ -s .vid/decide/halted ] && fail 'more did not clear the earlier set'; rm -rf .vid/decide; nh d1; rr_put "pr-6-$h-1" faults/ROW-001/control.txt ROW-009; rr_put "pr-6-$h-1" faults/ROW-001/cases-alpha.xml "$(rr_cases ROW-001=pass ROW-009=pass)"; r6 ROW-001=pass ROW-002-T2=pass $J; nh d2; rr_put "pr-6-$h-1" faults/ROW-001/control.txt ROW-009; rr_put "pr-6-$h-1" faults/ROW-001/cases-alpha.xml "$(rr_cases ROW-001=pass ROW-009=pass)"; r6 ROW-001=pass ROW-002-T2=pass $J; is ROW-001 'held — '; nh d3; r6 ROW-001=fail:a ROW-002-T2=pass $J; is ROW-001 'held — '; rm -rf .vid/decide; nh e1; rr_put "pr-6-$h-1" results.txt 'by: XX'; rr_send "pr-6-$h-1"; d6; rr_put "pr-6-$h-1" faults/ROW-001/control.txt ROW-009; rr_put "pr-6-$h-1" faults/ROW-001/cases-alpha.xml "$(rr_cases ROW-001=pass ROW-009=pass)"; r6 ROW-001=pass ROW-002-T2=pass $J; is ROW-001 'failing, a weak test'; rm -rf .vid/decide; nh f1; r6 ROW-001=fail:a ROW-002-T2=pass $J; nh f2; rr_put "pr-6-$h-1" results.txt 'by: XX'; rr_send "pr-6-$h-1"; d6; is ROW-001 'evidence missing'; rm -rf .vid/decide; nh g1; r6 ROW-001=pass ROW-002-T2=pass $J; is HOS-001 'accepted$'; nh g2; rm -rf "$T/r/pr-6-$h-1"; rr_put "pr-6-$h-1" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$X")"; rr_put "pr-6-$h-1" cases-alpha.xml "$(rr_cases ROW-001=pass ROW-002-T2=pass $J)"; rr_send "pr-6-$h-1"; d6; is HOS-001 'accepted$'; is ROW-002-T1 'accepted$'
rm -rf .vid/decide; nh b1; rr_put "pr-6-$h-1" faults/ROW-001/control.txt ROW-009; rr_put "pr-6-$h-1" faults/ROW-001/cases-alpha.xml "$(rr_cases ROW-001=pass ROW-009=pass)"; r6 ROW-001=pass ROW-002-T2=pass $J; is ROW-001 'failing, a weak test'; nh b2; r6 ROW-001=fail:a ROW-002-T2=pass $J; is ROW-001 'failing, a product'; nh b3; r6 ROW-001=pass ROW-002-T2=pass $J; is ROW-001 'accepted$'; [ "$(n ROW-001)" = 0 ] || fail 'a fix that works kept its count'
rm -rf .vid/decide; nh c1; r6 ROW-001=pass ROW-002-T2=pass $J; sed "s/^ROW-009	regression	n\/a	passed	n\/a	/ROW-009	regression	n\/a	failed	n\/a	T2: no case in alpha/" ".vid/results/pr-6-$h.txt" > "$T/ev"; cat "$T/ev" > ".vid/results/pr-6-$h.txt"; printf 't\tROW-009-T2\tlimit\t\tx\n' >> .vid/decide/rulings; sh "$DS" decide --ticket 3 --pr 6 --head "$X" > "$T/out" 2>&1; is ROW-009 'passing'
# v0.26.10.25.2 R8: size must fall. wk: a row's break missed at this head
wk() { for r; do rr_put "pr-6-$h-1" "faults/$r/control.txt" ROW-009; rr_put "pr-6-$h-1" "faults/$r/cases-alpha.xml" "$(rr_cases "$r=pass" ROW-009=pass)"; done; }; P='ROW-002-T1=pass ROW-009=pass HOS-001=pass'; held() { is "$1" 'held — it did not shrink'; grep -qx "6	$1" .vid/decide/halted || fail "no halt on $1"; }; hn() { rm -rf .vid/decide; for g in $(git --git-dir=.vid/code for-each-ref --format='%(refname)' 'refs/heads/vid-results/grade-pr-6-*'); do git --git-dir=.vid/code update-ref -d "$g"; done; }
# S02's own sets: {A}, {B}: B held a round sooner; {C, B}: the new row held too, the earlier one stands held
hn; nh s1; wk ROW-001; r6 ROW-001=pass ROW-002-T2=pass RULE-001=pass $P; is ROW-001 'failing, a weak test'; nh s2; wk ROW-002-T2; r6 ROW-001=pass ROW-002-T2=pass RULE-001=pass $P; held ROW-002-T2; is ROW-001 'accepted$'; nh s3; wk ROW-002-T2 RULE-001; r6 ROW-001=pass ROW-002-T2=pass RULE-001=pass $P; held ROW-002-T2; held RULE-001
# a weak row's first product failure leaves the count and gets its fixer, beside a new row at the count, which is held
hn; nh w1; wk ROW-001; r6 ROW-001=pass ROW-002-T2=pass RULE-001=pass $P; nh w2; r6 ROW-001=fail:a ROW-002-T2=fail:b RULE-001=pass $P; is ROW-001 'failing, a product'; held ROW-002-T2
# a `test it` row's first product failure, by its list: line; a row with none, at the same count, is held
hn; nh t1; rr_put "grade-pr-6-$h-1" grade.txt "$(printf 'by: GR\ncommit: %s\nROW-001 breached product — a wrong\nRULE-001 kept — seen' "$X")"; rr_send "grade-pr-6-$h-1"; r6 ROW-001=pass ROW-002-T2=fail:b RULE-001=pass $P; nh t2; r6 ROW-001=fail:a ROW-002-T2=pass RULE-001=pass $P; is ROW-001 'failing, a product'; [ ! -s .vid/decide/halted ] || fail 'a list row was counted'; grep -qx 'list: ROW-001' ".vid/results/pr-6-$h.txt" || fail 'no list line'; nh t3; hn; nh t4; rr_put "grade-pr-6-$h-1" grade.txt "$(printf 'by: GR\ncommit: %s\nROW-001 kept — seen' "$X")"; rr_send "grade-pr-6-$h-1"; r6 ROW-001=pass ROW-002-T2=fail:b RULE-001=pass $P; nh t5; r6 ROW-001=fail:a ROW-002-T2=pass RULE-001=pass $P; held ROW-001
# a new row with the count falling gets its round; two holds in a row; more clears the earlier set
hn; nh c1; r6 ROW-001=fail:a ROW-002-T2=fail:b RULE-001=pass $P; nh c2; r6 ROW-001=pass ROW-002-T2=pass RULE-001=fail:c $P; is RULE-001 'failing, a product'; [ ! -s .vid/decide/halted ] || fail 'a new row with the count falling was held'
hn; nh d1; r6 ROW-001=fail:a ROW-002-T2=pass RULE-001=pass $P; nh d2; r6 ROW-001=pass ROW-002-T2=fail:b RULE-001=pass $P; held ROW-002-T2; nh d3; r6 ROW-001=pass ROW-002-T2=pass RULE-001=fail:c $P; held RULE-001; [ "$(wc -l < .vid/decide/halted | tr -d ' ')" = 2 ] || fail 'two holds, not two rows held'; sh "$DS" rule RULE-001 more 3 > "$T/q"; sh "$DS" rule ROW-002-T2 more 3 > "$T/q" 2>&1 || true; d6; [ -s .vid/decide/halted ] && fail 'more left the halt'; nh d4; r6 ROW-001=pass ROW-002-T2=pass RULE-001=fail:c $P; [ ! -s .vid/decide/halted ] || fail 'more did not clear the earlier set'
git --git-dir=.vid/code update-ref -d refs/heads/vid-results/red-3-1; rr_put "pr-8-$h-1" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$X")"; rr_put "pr-8-$h-1" cases-alpha.xml "$(rr_cases $RR_ALL)"; rr_put "pr-8-$h-1" faults/ROW-001/inconclusive.txt 'it would not plant'; rr_send "pr-8-$h-1"; c0=$(n ROW-001); sh "$RS" read --ticket 3 --pr 8 --head "$X" > /dev/null 2>&1; sh "$DS" decide --ticket 3 --pr 8 --head "$X" > "$T/out" 2>&1; is ROW-001 'held — evidence missing — fault inconclusive'; [ "$(n ROW-001)" = "$c0" ] || fail 'inconclusive counted'; nh h2; rr_put "pr-8-$h-1" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$X")"; rr_put "pr-8-$h-1" cases-alpha.xml "$(rr_cases ROW-001=fail:x ROW-002-T1=pass ROW-002-T2=pass HOS-001=pass RULE-001=pass ROW-009=pass)"; rr_send "pr-8-$h-1"; sh "$RS" read --ticket 3 --pr 8 --head "$X" > /dev/null 2>&1; sh "$DS" decide --ticket 3 --pr 8 --head "$X" > "$T/out" 2>&1; is ROW-001 'held — failing'; rm -rf "$T/r/pr-8-$h-1"; nh h3; rr_put "pr-8-$h-1" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$X")"; rr_put "pr-8-$h-1" cases-alpha.xml "$(rr_cases $RR_ALL)"; rr_put "pr-8-$h-1" faults/ROW-001/inconclusive.txt 'it would not plant'; rr_send "pr-8-$h-1"; sh "$RS" read --ticket 3 --pr 8 --head "$X" > /dev/null 2>&1; sh "$DS" decide --ticket 3 --pr 8 --head "$X" > "$T/out" 2>&1; sh "$DS" rule ROW-001 accept > "$T/q" || fail 'accept could not reach an inconclusive row'
# v0.26.10.25.5 R4: ROW-001 landed after ticket 3 was published: a merge takes nothing for it from a decision before its landing, and
# none of ticket 3's reports is its evidence, so a head decided again brings nothing back
KEEP=''; hn; nh l1; rr_put "pr-6-$h-1" faults/ROW-001/control.txt ROW-009; rr_put "pr-6-$h-1" faults/ROW-001/cases-alpha.xml "$(rr_cases ROW-001=fail:x ROW-009=pass)"; r6 ROW-001=pass ROW-002-T2=pass $J; is ROW-001 'accepted$'; { grep -v '^row ROW-001 ' .vid/tw/handed || true; } > "$T/hd"; cat "$T/hd" > .vid/tw/handed
printf 'published 3 kind=step step=S01 rows=ROW-001 at=2026-11-01T00:00:00Z\nlanded 1 ids=ROW-001 at=2099-01-01T00:00:00Z\n' >> .vid/tw/log; printf 'ROW-001 abcdef123456 2099-01-01T00:00:00Z\n' > .vid/decide/landed
sh "$DS" merged --pr 6 > /dev/null 2>&1; ! grep -q '^row ROW-001 ' .vid/tw/handed || fail 'a merge took a landed row from a decision before its landing'
d6; ! grep -q '^ROW-001 ' "$T/out" || fail "an earlier ticket's report decided a landed row"; ! grep -q 'ROW-001' ".vid/results/pr-6-$h.txt" || fail "an earlier ticket's report is a landed row's evidence"
grep -q '^ROW-009 ' "$T/out" || fail 'the other rows went too'
exit 0
